const [tags, setTags] = useState<TagInputTag[]>([]);

<TagInput
  value={tags}
  onValueChange={setTags}
  label="Invite by email"
  placeholder="Names or emails"
  separators={/[\s,;]+/}
  normalize={(v) => v.toLowerCase()}
  validate={(v) => (/^\S+@\S+\.\S+$/.test(v) ? null : `“${v}” isn’t an email address`)}
/>
